    40	static bool
    41	_isBidi (const uint32_t *label, size_t llen)
    42	{
    43	  for (; (ssize_t) llen > 0; llen--) {
    44	    int bc = uc_bidi_category (*label++);
    45	
    46	    if (bc == UC_BIDI_R || bc == UC_BIDI_AL || bc == UC_BIDI_AN)
    47	      return 1;
    48	  }
    49	
    50	  return 0;
    51	}
    52	
    53	/* IDNA2008 BIDI check (RFC 5893) */
    54	int
    55	_idn2_bidi (const uint32_t * label, size_t llen)
    56	{
    57	  int bc;
    58	  int endok = 1;
    59	
    60	  if (!_isBidi (label, llen))
    61	    return IDN2_OK;
    62	
    63	  // 2.1
    64	  switch ((bc = uc_bidi_category (*label))) {
    65	    case UC_BIDI_L:
    66	      // check 2.5 & 2.6
    67	      for (size_t it = 1; it < llen; it++) {
    68	        bc = uc_bidi_category(label[it]);
    69	
    70	        if (bc == UC_BIDI_L || bc == UC_BIDI_EN || bc == UC_BIDI_NSM) {
    71	          endok = 1;
    72	        } else {
    73	          if (bc != UC_BIDI_ES && bc != UC_BIDI_CS && bc != UC_BIDI_ET && bc != UC_BIDI_ON && bc != UC_BIDI_BN) {
    74	            /* printf("LTR label contains invalid code point\n"); */
    75	            return IDN2_BIDI;
    76	          }
    77	          endok = 0;
    78	        }
    79	      }
    80	      /* printf("LTR label ends with invalid code point\n"); */
    81	      return endok ? IDN2_OK : IDN2_BIDI;
    82	
    83	    case UC_BIDI_R:
    84	    case UC_BIDI_AL:
    85	      // check 2.2, 2.3, 2.4
    86	      /* printf("Label[0]=%04X: %s\n", label[0], uc_bidi_category_name(bc)); */
    87	      for (size_t it = 1; it < llen; it++) {
    88	        bc = uc_bidi_category(label[it]);
    89	
    90	        /* printf("Label[%d]=%04X: %s\n", (int) it, label[it], uc_bidi_category_name(bc)); */
    91	        if (bc == UC_BIDI_R || bc == UC_BIDI_AL || bc == UC_BIDI_EN || bc == UC_BIDI_AN || bc == UC_BIDI_NSM) {
    92	          endok = 1;
    93	        } else {
    94	          if (bc != UC_BIDI_ES && bc != UC_BIDI_CS && bc != UC_BIDI_ET && bc != UC_BIDI_ON && bc != UC_BIDI_BN) {
    95	            /* printf("RTL label contains invalid code point\n"); */
    96	            return IDN2_BIDI;
    97	          }
    98	          endok = 0;
    99	        }
   100	      }
   101	      /* printf("RTL label ends with invalid code point\n"); */
   102	      return endok ? IDN2_OK : IDN2_BIDI;
   103	
   104	    default:
   105	      /* printf("Label begins with invalid BIDI class %s\n", uc_bidi_category_name(bc)); */
   106	      return IDN2_BIDI;
   107	  }
   108	}
